    "ACTIVE IND FUT": { ex: "Crās tē monēbimus.", en: "Tomorrow we shall warn you.", note: "simple future" },
    "ACTIVE IND PERF": { ex: "Senātus cōnsulem monuit.", en: "The senate warned the consul.", note: "completed past action" },
