    "ACTIVE IND FUTP": { ex: "Sī eum monueris, pārēbit.", en: "If you warn him, he will obey.", note: "future perfect in a sī-clause" },
    "ACTIVE SUB PRES": { ex: "Veniō ut tē moneam.", en: "I come to warn you.", note: "purpose clause with ut" },
    "ACTIVE SUB IMPF": { ex: "Mīsit servum quī mē monēret.", en: "He sent a slave to warn me.", note: "relative clause of purpose" },
    "ACTIVE SUB PERF": { ex: "Rogō quid tē monuerit.", en: "I ask what he warned you about.", note: "indirect question, primary sequence" },
    "ACTIVE SUB PLUP": { ex: "Nisi tē monuissem, periissēs.", en: "If I had not warned you, you would have perished.", note: "past contrary-to-fact condition" },
    "PASSIVE IND PRES": { ex: "Ā patre moneor.", en: "I am being warned by my father.", note: "ablative of agent" },
    "PASSIVE IND IMPF": { ex: "Mīlitēs cotīdiē monēbantur.", en: "The soldiers were warned daily.", note: "habitual past, passive" },
    "PASSIVE IND FUT": { ex: "Monēbimur dē perīculō.", en: "We shall be warned of the danger.", note: "future passive" },
