    "PASSIVE IND PLUP": { ex: "Monitī erant, tamen fūgērunt.", en: "They had been warned, yet they fled.", note: "participle + erant" },
    "PASSIVE IND FUTP": { ex: "Priusquam veniat, monitus erit.", en: "Before he comes, he will have been warned.", note: "participle + erit" },
