    "IMP ACTIVE PRES": { ex: "Monē frātrem tuum!", en: "Warn your brother!", note: "direct command (plural monēte)" },
    "IMP ACTIVE FUT": { ex: "Monētō cīvēs.", en: "You shall warn the citizens.", note: "future imperative" },
    "IMP PASSIVE PRES": { ex: "Monēre ā sapientibus.", en: "Be warned by the wise.", note: "passive imperative; rare" },
    "IMP PASSIVE FUT": { ex: "Monētor ā maiōribus.", en: "You shall be warned by your elders.", note: "future passive imperative; very rare" },
