/* ======================= DEPONENTS ======================= */
PACKS["V-1-DEP"] = {
  id: "V-1-DEP",
  title: "First conjugation deponent: hortor",
  pos: "V",
  model: { hw: "hortor", parts: "hortor, hortārī, hortātus sum", gloss: "to urge, encourage" },
  modelEntry: { s: ["hort", "hort", null, "hortat"], p: "V", c: [1, 1], k: "DEP" },
  intro: "<p>A <b>deponent</b> verb has <i>passive forms</i> but <i>active meaning</i>: hortor means “I urge”, not “I am urged”. It has only three principal parts — hortor, hortārī, hortātus sum — all passive in shape. Recognise the conjugation from the infinitive: <b>-ārī</b> = first (hortārī, cōnārī, arbitrārī), -ērī = second, -ī = third, -īrī = fourth.</p><p>Deponents have “laid aside” (dēpōnere) their active forms, with four exceptions that keep active shape: the present participle (hortāns), the future participle (hortātūrus), the future infinitive (hortātūrus esse) and the gerund (hortandī). The gerundive (hortandus) keeps its normal passive meaning, “to be urged”.</p>",
  formation: "<p>Every finite form is built exactly like the passive of amō: present hortor, hortāris (or hortāre), hortātur, hortāmur, hortāminī, hortantur; imperfect hortābar; future hortābor; subjunctive horter, hortārer. Perfect system = perfect participle + sum: hortātus sum, hortātus eram, hortātus erō, hortātus sim, hortātus essem.</p><p>Imperative: singular <b>hortāre</b> (looks like an active infinitive!), plural hortāminī; future hortātor. Infinitives: hortārī (present), hortātus esse (perfect), hortātūrus esse (future).</p>",
  rows: {
    "PASSIVE IND PRES": { ex: "Mīlitēs hortor.", en: "I urge the soldiers.", note: "passive form, active meaning, direct object" },
    "PASSIVE IND IMPF": { ex: "Dux mīlitēs hortābātur.", en: "The general was urging the soldiers.", note: "ongoing past" },
    "PASSIVE IND FUT": { ex: "Vōs hortābimur.", en: "We shall urge you.", note: "future" },
    "PASSIVE IND PERF": { ex: "Cōnsul populum hortātus est.", en: "The consul urged the people.", note: "participle + est, active sense" },
    "PASSIVE IND PLUP": { ex: "Eōs iam hortātī erāmus.", en: "We had already urged them.", note: "participle + erāmus" },
    "PASSIVE IND FUTP": { ex: "Cum eōs hortātus erō, pugnābunt.", en: "When I have urged them, they will fight.", note: "participle + erō" },
    "PASSIVE SUB PRES": { ex: "Veniō ut tē horter.", en: "I come to urge you.", note: "purpose clause" },
    "PASSIVE SUB IMPF": { ex: "Mīsit lēgātōs quī hortārentur.", en: "He sent envoys to urge them.", note: "relative clause of purpose" },
    "PASSIVE SUB PERF": { ex: "Rogās quid eōs hortātus sim.", en: "You ask what I urged them to do.", note: "indirect question" },
    "PASSIVE SUB PLUP": { ex: "Sī mē hortātus essēs, mānsissem.", en: "If you had urged me, I would have stayed.", note: "past contrary-to-fact" },
    "IMP PASSIVE PRES": { ex: "Hortāre amīcōs tuōs!", en: "Urge your friends!", note: "deponent imperative in -re (plural hortāminī)" },
    "IMP PASSIVE FUT": { ex: "Hortātor mīlitēs.", en: "You shall urge the soldiers.", note: "future imperative" },
    "INF PASSIVE PRES": { ex: "Mīlitēs hortārī dēbet.", en: "He ought to urge the soldiers.", note: "complementary infinitive" },
    "INF PASSIVE PERF": { ex: "Dīcit sē eōs hortātum esse.", en: "He says that he urged them.", note: "indirect statement, prior time" },
    "INF ACTIVE FUT": { ex: "Spērō eum nōs hortātūrum esse.", en: "I hope that he will urge us.", note: "active-form future infinitive" },
    "PPL ACTIVE PRES": { ex: "Dux, mīlitēs hortāns, prōcessit.", en: "The general advanced, urging his soldiers.", note: "active-form present participle" },
    "PPL PASSIVE PERF": { ex: "Mīlitēs hortātus, signum dedit.", en: "Having urged the soldiers, he gave the signal.", note: "perfect participle with ACTIVE meaning" },
    "PPL ACTIVE FUT": { ex: "Hortātūrus mīlitēs surrēxit.", en: "He stood up to urge the soldiers.", note: "future participle: intention" },
    "PPL PASSIVE FUT": { ex: "Mīlitēs hortandī sunt.", en: "The soldiers must be urged.", note: "gerundive keeps passive meaning" },
    "GERUND": { ex: "Hortandī causā vēnit.", en: "He came for the sake of urging.", note: "gerund (active meaning)" },
    "SUPINE": { ex: "Vēnit mīlitēs hortātum.", en: "He came to urge the soldiers.", note: "supine of purpose" }
  },
  tips: [
    "Translate deponents actively — always. hortātus est = “he urged”, never “he was urged”.",
    "The perfect participle of a deponent is the only Latin participle that is past AND active: hortātus = “having urged”. Very handy in narrative.",
    "The singular imperative hortāre looks like an active infinitive; the plural hortāminī looks like the 2nd plural indicative. Context decides.",
    "Deponents take direct objects in the accusative like any transitive verb (hortor mīlitēs). Some take other cases: ūtor, fruor, fungor, potior, vēscor + ablative.",
    "Common first-conjugation deponents: cōnor, arbitror, hortor, mīror, moror, precor, recordor, vēnor, versor."
  ],
  related: ["V-1", "V-2-DEP", "V-3-DEP", "V-SEMIDEP"]
};

