    "ACTIVE SUB PRES": { ex: "Quis hoc facere audeat?", en: "Who would dare to do this?", note: "potential subjunctive" },
    "ACTIVE SUB IMPF": { ex: "Tam timidus erat ut loquī nōn audēret.", en: "He was so timid that he did not dare to speak.", note: "result clause" },
    "PASSIVE IND PERF": { ex: "Hoc dīcere ausus sum.", en: "I dared to say this.", note: "passive form, active meaning" },
    "PASSIVE IND PLUP": { ex: "Nēmō id ausus erat.", en: "No one had dared it.", note: "participle + erat" },
    "PASSIVE IND FUTP": { ex: "Sī hoc ausus eris, laudāberis.", en: "If you dare this, you will be praised.", note: "participle + eris" },
    "PASSIVE SUB PERF": { ex: "Mīror quid ausus sīs.", en: "I wonder what you dared.", note: "indirect question" },
    "PASSIVE SUB PLUP": { ex: "Sī ausī essent, vīcissent.", en: "If they had dared, they would have won.", note: "past contrary-to-fact" },
    "IMP ACTIVE PRES": { ex: "Audē sapere!", en: "Dare to be wise!", note: "direct command (Horace: sapere audē)" },
    "IMP ACTIVE FUT": { ex: "Audētō loquī.", en: "You shall dare to speak.", note: "future imperative" },
    "INF ACTIVE PRES": { ex: "Audēre nōn possum.", en: "I cannot bring myself to dare.", note: "complementary infinitive" },
