    "INF ACTIVE FUT": { ex: "Putō eum ausūrum esse.", en: "I think that he will dare.", note: "future infinitive" },
    "PPL ACTIVE PRES": { ex: "Audēns omnia vincit.", en: "The daring one conquers all.", note: "participle as noun" },
    "PPL PASSIVE PERF": { ex: "Multa ausus, tandem cecidit.", en: "Having dared much, he finally fell.", note: "perfect participle, active meaning" },
    "PPL ACTIVE FUT": { ex: "Pugnāre ausūrus, arma cēpit.", en: "About to dare to fight, he took up arms.", note: "future participle" },
