    "ACTIVE SUB PRES": { ex: "Labōrā ut vincere possīs.", en: "Work so that you can win.", note: "purpose clause" },
    "ACTIVE SUB IMPF": { ex: "Tam fessus erat ut stāre nōn posset.", en: "He was so tired that he could not stand.", note: "result clause" },
