    "ACTIVE SUB IMPF": { ex: "Timēbam nē hoc fieret.", en: "I feared that this might happen.", note: "fear clause; short i before -er-" },
    "PASSIVE IND PERF": { ex: "Cōnsul factus est.", en: "He became consul.", note: "perfect from faciō’s participle" },
    "PASSIVE IND PLUP": { ex: "Iam factum erat.", en: "It had already been done.", note: "participle + erat" },
